SELECT c.table_name,c.ordinal_position,c.column_name,c.column_type,c.is_nullable,IF(c.column_default IS NULL,'NULL',CONCAT('HEX:',HEX(c.column_default))),c.extra,COALESCE(c.character_set_name,''),COALESCE(c.collation_name,'') FROM information_schema.columns c JOIN information_schema.tables t ON t.table_schema=c.table_schema AND t.table_name=c.table_name WHERE c.table_schema='acore_world' AND t.table_type='BASE TABLE' AND c.table_name NOT REGEXP '(_locale$|^smart_scripts$|^waypoint|^script_waypoint$|^spell_script_names$|^creature_text$|^updates|^version$|^command$|^acore_string$)' ORDER BY BINARY c.table_name,c.ordinal_position;
